with remaining_keys as (select status from shipments except select status from shipments where shipped_date < '2025-05-09'), kept_rows as (select s.* from shipments s inner join remaining_keys k on s.status = k.status) select order_id, percentile_approx(cost, array(0.25, 0.5, 0.75)) as cost_quartiles, count(*) filter (where status = 'DELIVERED') as delivered_rows, count(distinct carrier) as distinct_carriers, stddev_samp(cost) as cost_stddev, approx_percentile(cost, array(0.25, 0.5, 0.75)) as cost_quartiles_2 from kept_rows group by order_id
